SELECT COALESCE(SUM(amount), 0)
FROM TRANSACTIONS
WHERE user_id = #{userId}
  AND type = 'EXPENSE'
  AND transaction_date BETWEEN #{condition.startDate} AND #{condition.endDate}

SELECT COALESCE(SUM(amount), 0)
FROM TRANSACTIONS
WHERE user_id = #{userId}
  AND type = 'INCOME'
  AND transaction_date BETWEEN #{condition.startDate} AND #{condition.endDate}

SELECT COUNT(*)
FROM TRANSACTIONS
WHERE user_id = #{userId}
  AND transaction_date BETWEEN #{condition.startDate} AND #{condition.endDate}
  AND category <> 'CARD_WITHDRAWAL'
